        /// Format: `pve-node`.
        public var node: String

        /// The (unique) ID of the VM.
        ///
        /// Range: 100…999999999. Format: `pve-vmid`.
        public var vmid: Int

        /// Do not deactivate storage volumes.
        ///
        /// Default: `0`.
        public var keepActive: Bool?

        /// The cluster node name.
        ///
        /// Format: `pve-node`.
        public var migratedfrom: String?

        /// Try to abort active 'qmshutdown' tasks before stopping.
        ///
        /// Default: `0`.
        public var overruleShutdown: Bool?

        /// Ignore locks - only root is allowed to use this option.
        public var skiplock: Bool?

        /// Wait maximal timeout seconds.
        ///
        /// Minimum: 0.
        public var timeout: Int?

        public init(node: String, vmid: Int) {
            self.node = node
            self.vmid = vmid
        }

        public var path: String { PathBuilder.path("nodes", node.parameterValue, "qemu", vmid.parameterValue, "status", "stop") }

        public var parameters: [(String, String)] {
            var result: [(String, String)] = []
            if let value = keepActive { result.append(("keepActive", value.parameterValue)) }
            if let value = migratedfrom { result.append(("migratedfrom", value.parameterValue)) }
            if let value = overruleShutdown { result.append(("overrule-shutdown", value.parameterValue)) }
            if let value = skiplock { result.append(("skiplock", value.parameterValue)) }
            if let value = timeout { result.append(("timeout", value.parameterValue)) }
            return result
        }
    }

