            return result
        }
    }

    /// `POST /nodes/{node}/qemu/{vmid}/vncproxy`
    ///
    /// Creates a TCP VNC proxy connections.
    public struct PostNodesQemuVncproxy: PVEAPIRequest, Hashable {
        public typealias Response = Output
        public static let method: HTTPMethod = .post
        public static let pathTemplate = "/nodes/{node}/qemu/{vmid}/vncproxy"
        public static let schemaName = "vncproxy"

        /// The cluster node name.
        ///
        /// Format: `pve-node`.
        public var node: String

        /// The (unique) ID of the VM.
        ///
        /// Range: 100…999999999. Format: `pve-vmid`.
        public var vmid: Int

        /// Deprecated, do not use. Password is generated when required.
        ///
        /// Default: `0`.
        public var generatePassword: Bool?

        /// Prepare for websocket upgrade (only required when using serial terminal, otherwise upgrade is always possible).
        public var websocket: Bool?

        public init(node: String, vmid: Int) {
            self.node = node
            self.vmid = vmid
        }

        public var path: String { PathBuilder.path("nodes", node.parameterValue, "qemu", vmid.parameterValue, "vncproxy") }

        public var parameters: [(String, String)] {
            var result: [(String, String)] = []
            if let value = generatePassword { result.append(("generate-password", value.parameterValue)) }
            if let value = websocket { result.append(("websocket", value.parameterValue)) }
            return result
        }

        public struct Output: Decodable, Sendable, Hashable {
            public var cert: String?
            /// Password used for authentication within the VNC protocol. Consists of printable ASCII characters ('!' .. '~').
            public var password: String?
            public var port: Int?
            public var ticket: String?
            public var upid: String?
            public var user: String?

            public init(from decoder: any Decoder) throws {
                let c = try decoder.container(keyedBy: AnyCodingKey.self)
                cert = c.flexibleString(AnyCodingKey("cert"))
                password = c.flexibleString(AnyCodingKey("password"))
                port = c.flexibleInt(AnyCodingKey("port"))
                ticket = c.flexibleString(AnyCodingKey("ticket"))
                upid = c.flexibleString(AnyCodingKey("upid"))
                user = c.flexibleString(AnyCodingKey("user"))
            }
        }
    }

